[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>The History of Books - Infographic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;800;900&family=Source+Sans+3:wght@300;400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2384px;
    height: 3370px;
    background: #f5f0e8;
    font-family: 'Source Sans 3', 'Segoe UI', sans-serif;
    color: #2c1810;
    overflow: hidden;
    position: relative;
  }

  /* Subtle paper texture overlay */
  body::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      repeating-linear-gradient(
        0deg,
        transparent,
        transparent 3px,
        rgba(139, 90, 43, 0.015) 3px,
        rgba(139, 90, 43, 0.015) 4px
      ),
      repeating-linear-gradient(
        90deg,
        transparent,
        transparent 3px,
        rgba(139, 90, 43, 0.01) 3px,
        rgba(139, 90, 43, 0.01) 4px
      );
    pointer-events: none;
    z-index: 0;
  }

  .poster {
    width: 100%;
    height: 100%;
    padding: 80px 90px 70px;
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
  }

  /* ── HEADER ── */
  .header {
    text-align: center;
    margin-bottom: 50px;
    padding-bottom: 40px;
    border-bottom: 3px solid #8B4513;
    position: relative;
  }

  .header::after {
    content: '';
    position: absolute;
    bottom: -7px;
    left: 50%;
    transform: translateX(-50%);
    width: 60%;
    height: 1px;
    background: #8B4513;
  }

  .header .kicker {
    font-family: 'Source Sans 3', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 6px;
    text-transform: uppercase;
    color: #C45A20;
    margin-bottom: 18px;
  }

  .header h1 {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 86px;
    font-weight: 800;
    line-height: 1.05;
    color: #1a0e08;
    margin-bottom: 20px;
    letter-spacing: -1px;
  }

  .header h1 em {
    font-style: italic;
    color: #8B4513;
  }

  .header .subtitle {
    font-size: 26px;
    font-weight: 300;
    color: #5a3e2b;
    max-width: 1400px;
    margin: 0 auto;
    line-height: 1.5;
  }

  /* ── KEY METRICS BAR ── */
  .metrics-bar {
    display: flex;
    justify-content: center;
    gap: 60px;
    margin-bottom: 50px;
    padding: 30px 40px;
    background: linear-gradient(135deg, #3b1f0b 0%, #5a2d0c 50%, #3b1f0b 100%);
    border-radius: 16px;
    box-shadow: 0 6px 30px rgba(59, 31, 11, 0.3);
  }

  .metric-item {
    text-align: center;
  }

  .metric-item .metric-value {
    font-family: 'Playfair Display', serif;
    font-size: 42px;
    font-weight: 700;
    color: #f0c87a;
  }

  .metric-item .metric-label {
    font-size: 16px;
    font-weight: 500;
    color: #d4b896;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-top: 4px;
  }

  /* ── SECTION LAYOUT ── */
  .section {
    margin-bottom: 40px;
    position: relative;
  }

  .section-header {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-bottom: 20px;
  }

  .section-number {
    font-family: 'Playfair Display', serif;
    font-size: 50px;
    font-weight: 900;
    color: #C45A20;
    opacity: 0.35;
    line-height: 1;
  }

  .section-title {
    font-family: 'Playfair Display', serif;
    font-size: 38px;
    font-weight: 700;
    color: #2c1810;
    line-height: 1.2;
  }

  .section-desc {
    font-size: 20px;
    color: #5a3e2b;
    line-height: 1.6;
    max-width: 1100px;
    margin-bottom: 20px;
    font-weight: 300;
  }

  /* ── MAIN CHART AREA (Timeline) ── */
  .main-chart-area {
    background: #fffcf5;
    border: 2px solid #d4b896;
    border-radius: 20px;
    padding: 40px 50px 30px;
    margin-bottom: 10px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.06);
    position: relative;
    flex-shrink: 0;
  }

  .main-chart-area .chart-annotation {
    position: absolute;
    top: 25px;
    right: 50px;
    background: #C45A20;
    color: white;
    padding: 8px 20px;
    border-radius: 20px;
    font-size: 15px;
    font-weight: 600;
    letter-spacing: 0.5px;
  }

  .infographic-container {
    width: 100%;
    min-height: 300px;
  }

  /* ── TWO COLUMN LAYOUT ── */
  .two-col {
    display: flex;
    gap: 40px;
    flex: 1;
    min-height: 0;
  }

  .col-left {
    flex: 1.1;
    display: flex;
    flex-direction: column;
    gap: 30px;
  }

  .col-right {
    flex: 0.9;
    display: flex;
    flex-direction: column;
    gap: 30px;
  }

  .card {
    background: #fffcf5;
    border: 2px solid #d4b896;
    border-radius: 20px;
    padding: 35px 40px 25px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.06);
    flex: 1;
    display: flex;
    flex-direction: column;
  }

  .card .infographic-container {
    flex: 1;
    min-height: 250px;
  }

  /* ── GUTENBERG CALLOUT ── */
  .gutenberg-callout {
    background: linear-gradient(135deg, #5a2d0c 0%, #8B4513 100%);
    border-radius: 20px;
    padding: 35px 40px;
    color: #f5f0e8;
    display: flex;
    align-items: center;
    gap: 30px;
    box-shadow: 0 6px 30px rgba(90, 45, 12, 0.3);
  }

  .gutenberg-callout .callout-icon {
    font-size: 80px;
    line-height: 1;
    flex-shrink: 0;
  }

  .gutenberg-callout .callout-text h3 {
    font-family: 'Playfair Display', serif;
    font-size: 30px;
    font-weight: 700;
    margin-bottom: 10px;
    color: #f0c87a;
  }

  .gutenberg-callout .callout-text p {
    font-size: 19px;
    line-height: 1.55;
    color: #e8d5c0;
    font-weight: 300;
  }

  /* ── MIRROR SECTION ── */
  .mirror-section {
    background: linear-gradient(135deg, #2c1810 0%, #3b1f0b 100%);
    border-radius: 20px;
    padding: 35px 40px;
    color: #f5f0e8;
  }

  .mirror-section h3 {
    font-family: 'Playfair Display', serif;
    font-size: 32px;
    font-weight: 700;
    color: #f0c87a;
    margin-bottom: 16px;
  }

  .mirror-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 25px;
  }

  .mirror-item {
    text-align: center;
    padding: 18px 12px;
    border: 1px solid rgba(212, 184, 150, 0.3);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.05);
  }

  .mirror-item .mirror-icon {
    font-size: 36px;
    margin-bottom: 10px;
  }

  .mirror-item .mirror-label {
    font-family: 'Playfair Display', serif;
    font-size: 20px;
    font-weight: 600;
    color: #f0c87a;
    margin-bottom: 6px;
  }

  .mirror-item .mirror-desc {
    font-size: 15px;
    color: #d4b896;
    line-height: 1.45;
    font-weight: 300;
  }

  /* ── CUSTOM TIMELINE CHART ── */
  .timeline-chart {
    width: 100%;
    height: 380px;
    position: relative;
  }

  .timeline-chart svg {
    width: 100%;
    height: 100%;
  }

  /* ── FOOTER ── */
  .footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
    padding-top: 25px;
    border-top: 2px solid #d4b896;
    font-size: 15px;
    color: #8a7260;
  }

  .footer .sources {
    max-width: 70%;
    line-height: 1.5;
  }

  .footer .branding {
    font-family: 'Playfair Display', serif;
    font-size: 18px;
    font-weight: 600;
    color: #5a3e2b;
  }

  /* ── CUSTOM BAR CHART ── */
  .bar-chart-custom {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 10px 0;
  }

  .bar-row {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .bar-label {
    width: 140px;
    text-align: right;
    font-size: 16px;
    font-weight: 500;
    color: #3b1f0b;
    flex-shrink: 0;
  }

  .bar-track {
    flex: 1;
    height: 30px;
    background: #ede4d6;
    border-radius: 6px;
    overflow: hidden;
    position: relative;
  }

  .bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.3s;
    position: relative;
  }

  .bar-value {
    position: absolute;
    right: -55px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 15px;
    font-weight: 600;
    color: #5a3e2b;
    white-space: nowrap;
  }

  .bar-fill .bar-value-inside {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 14px;
    font-weight: 700;
    color: white;
  }

  .per-capita-note {
    font-size: 14px;
    color: #8a7260;
    font-style: italic;
    margin-top: 8px;
  }
</style>
</head>
<body>
<div class="poster">
  <!-- HEADER -->
  <div class="header">
    <div class="kicker">A Data-Driven Exploration</div>
    <h1>The History of <em>Books</em></h1>
    <div class="subtitle">From rare handwritten manuscripts to millions of printed titles — how book production evolved over 1,500 years, and why it matters for civilization.</div>
  </div>

  <!-- KEY METRICS -->
  <div class="metrics-bar">
    <div class="metric-item">
      <div class="metric-value">~1440</div>
      <div class="metric-label">Gutenberg's Press</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">10+</div>
      <div class="metric-label">Centuries of Manuscripts</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">500+</div>
      <div class="metric-label">Years of Print Data</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">>49 pp.</div>
      <div class="metric-label">UNESCO Book Standard</div>
    </div>
    <div class="metric-item">
      <div class="metric-value">2.2M+</div>
      <div class="metric-label">Titles Published / Year (Global)</div>
    </div>
  </div>

  <!-- SECTION 1: MAIN TIMELINE CHART -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">01</div>
      <div>
        <div class="section-title">The Long Arc: Manuscripts to Mass Production</div>
      </div>
    </div>
    <div class="section-desc">Estimated European book output over 15 centuries. The contrast between the slow accumulation of manuscripts and the explosive growth after Gutenberg's press (~1440) is the defining story of knowledge dissemination.</div>
    <div class="main-chart-area">
      <div class="chart-annotation">&#9733; Gutenberg Inflection Point</div>
      <div class="timeline-chart">
        <svg viewBox="0 0 2100 370" xmlns="http://www.w3.org/2000/svg">
          <!-- Grid lines -->
          <defs>
            <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="#C45A20" stop-opacity="0.6"/>
              <stop offset="100%" stop-color="#C45A20" stop-opacity="0.05"/>
            </linearGradient>
            <linearGradient id="msGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="#8B4513" stop-opacity="0.4"/>
              <stop offset="100%" stop-color="#8B4513" stop-opacity="0.05"/>
            </linearGradient>
            <filter id="glow">
              <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
              <feMerge>
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
          </defs>

          <!-- Y-axis labels -->
          <text x="55" y="340" fill="#8a7260" font-size="14" text-anchor="end" font-family="Source Sans 3">0</text>
          <text x="55" y="270" fill="#8a7260" font-size="14" text-anchor="end" font-family="Source Sans 3">5K</text>
          <text x="55" y="200" fill="#8a7260" font-size="14" text-anchor="end" font-family="Source Sans 3">50K</text>
          <text x="55" y="130" fill="#8a7260" font-size="14" text-anchor="end" font-family="Source Sans 3">500K</text>
          <text x="55" y="60" fill="#8a7260" font-size="14" text-anchor="end" font-family="Source Sans 3">5M+</text>

          <!-- Horizontal grid -->
          <line x1="70" y1="335" x2="2070" y2="335" stroke="#d4b896" stroke-width="1" stroke-opacity="0.5"/>
          <line x1="70" y1="265" x2="2070" y2="265" stroke="#d4b896" stroke-width="1" stroke-opacity="0.3" stroke-dasharray="6,4"/>
          <line x1="70" y1="195" x2="2070" y2="195" stroke="#d4b896" stroke-width="1" stroke-opacity="0.3" stroke-dasharray="6,4"/>
          <line x1="70" y1="125" x2="2070" y2="125" stroke="#d4b896" stroke-width="1" stroke-opacity="0.3" stroke-dasharray="6,4"/>
          <line x1="70" y1="55" x2="2070" y2="55" stroke="#d4b896" stroke-width="1" stroke-opacity="0.3" stroke-dasharray="6,4"/>

          <!-- X-axis century labels -->
          <text x="120" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">6th C</text>
          <text x="250" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">7th</text>
          <text x="380" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">8th</text>
          <text x="510" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">9th</text>
          <text x="640" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">10th</text>
          <text x="770" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">11th</text>
          <text x="900" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">12th</text>
          <text x="1030" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">13th</text>
          <text x="1160" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">14th</text>
          <text x="1290" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">15th</text>
          <text x="1420" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="600">16th</text>
          <text x="1550" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">17th</text>
          <text x="1680" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">18th</text>
          <text x="1810" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">19th</text>
          <text x="1940" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">20th</text>
          <text x="2050" y="360" fill="#5a3e2b" font-size="15" text-anchor="middle" font-family="Source Sans 3" font-weight="500">21st</text>

          <!-- MANUSCRIPT ERA - gentle area (log scale representation) -->
          <!-- Values: 6thC~120, 7thC~240, 8thC~580, 9thC~1800, 10thC~2100, 11thC~3600, 12thC~7700, 13thC~10000, 14thC~18000, 15thC~28000 -->
          <path d="M120,333 L250,331 L380,327 L510,315 L640,312 L770,300 L900,280 L1030,272 L1160,255 L1290,238 L1290,335 L120,335 Z" fill="url(#msGrad)"/>
          <path d="M120,333 L250,331 L380,327 L510,315 L640,312 L770,300 L900,280 L1030,272 L1160,255 L1290,238" fill="none" stroke="#8B4513" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>

          <!-- Data points for manuscript era -->
          <circle cx="120" cy="333" r="4" fill="#8B4513"/>
          <circle cx="250" cy="331" r="4" fill="#8B4513"/>
          <circle cx="380" cy="327" r="4" fill="#8B4513"/>
          <circle cx="510" cy="315" r="5" fill="#8B4513"/>
          <circle cx="640" cy="312" r="4" fill="#8B4513"/>
          <circle cx="770" cy="300" r="4" fill="#8B4513"/>
          <circle cx="900" cy="280" r="5" fill="#8B4513"/>
          <circle cx="1030" cy="272" r="4" fill="#8B4513"/>
          <circle cx="1160" cy="255" r="5" fill="#8B4513"/>
          <circle cx="1290" cy="238" r="6" fill="#8B4513"/>

          <!-- Annotations on manuscript line -->
          <text x="515" y="305" fill="#8B4513" font-size="13" font-family="Source Sans 3" font-weight="600" text-anchor="middle">Carolingian</text>
