.gutenberg-callout .callout-text h3 {
  font-family: 'Playfair Display', serif;
  font-size: 26px;
  font-weight: 700;
  margin-bottom: 8px;
  color: #f0c87a;
}

.gutenberg-callout .callout-text p {
  font-size: 17px;
  line-height: 1.5;
  color: #e8d5c0;
  font-weight: 300;
}

/* ── MIRROR SECTION ── */
.mirror-section {
  background: linear-gradient(135deg, #2c1810 0%, #3b1f0b 100%);
  border-radius: 20px;
  padding: 25px 30px;
  color: #f5f0e8;
}

.mirror-section h3 {
  font-family: 'Playfair Display', serif;
  font-size: 28px;
  font-weight: 700;
  color: #f0c87a;
  margin-bottom: 14px;
}

.mirror-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

.mirror-item {
  text-align: center;
  padding: 14px 10px;
  border: 1px solid rgba(212, 184, 150, 0.3);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
}

.mirror-item .mirror-icon {
  font-size: 30px;
  margin-bottom: 8px;
}

.mirror-item .mirror-label {
  font-family: 'Playfair Display', serif;
  font-size: 18px;
  font-weight: 600;
  color: #f0c87a;
  margin-bottom: 4px;
}

.mirror-item .mirror-desc {
  font-size: 14px;
  color: #d4b896;
  line-height: 1.4;
  font-weight: 300;
}

/* ── CUSTOM TIMELINE CHART ── */
.timeline-chart {
  width: 100%;
  height: 340px;
  position: relative;
}

.timeline-chart svg {
  width: 100%;
  height: 100%;
}

/* ── FOOTER ── */
.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  padding-top: 18px;
  border-top: 2px solid #d4b896;
  font-size: 14px;
  color: #8a7260;
}

.footer .sources {
  max-width: 70%;
  line-height: 1.5;
}

.footer .branding {
  font-family: 'Playfair Display', serif;
  font-size: 18px;
  font-weight: 600;
  color: #5a3e2b;
}

/* ── CUSTOM BAR CHART ── */
.bar-chart-custom {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 6px 0;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bar-label {
  width: 130px;
  text-align: right;

